#include<bits/stdc++.h>using namespace std; int main(){    int t;    cin >> t;    while(t--)    {       int n;       cin >> n;       vector<string> s(n);       for(int i=0;i<n;i++)       {           cin >> s[i];       }       vector<int> store(n);       for(int i=0;i<n;i++)       {           for(int j=0;j<4;j++)           {               if(s[i][j] == '#')               {                   store[i] = j;               }           }       }       reverse(store.begin(),store.end());       for(int i=0;i<n;i++)       {           cout << store[i]+1 <<" ";       }       cout <<  endl;    }}